#include <iostream>
using namespace std;

int main() {
    int n;
    if (!(cin >> n)) return 0;
    long long a[15];
    for (int i = 0; i <= n; i++) cin >> a[i];
    long long x;
    cin >> x;

    long long result = a[n];
    for (int i = n - 1; i >= 0; i--) {
        result = result * x + a[i];
    }
    cout << result << "\n";
    return 0;
}
